#!/usr/bin/env python3
"""Generate lab schema tables from the draft only; no production generation."""
import json
from pathlib import Path
import re
import sys
import tempfile
import shutil

root=Path(__file__).resolve().parent
original=root
scratch=None
if '--check' in sys.argv:
    scratch=tempfile.TemporaryDirectory(prefix='ra-schema-');root=Path(scratch.name)
    (root/'wire').mkdir();(root/'go/labwire').mkdir(parents=True)
    for name in ['transport-draft.proto','body-bounds.json','body-relations.json']:shutil.copy(original/'wire'/name,root/'wire'/name)
source=re.sub(r'//[^\n]*','',(root/'wire/transport-draft.proto').read_text())
enums={name:max(map(int,re.findall(r'=\s*(\d+)',body))) for name,body in re.findall(r'enum\s+(\w+)\s*\{([^}]+)\}',source)}
schemas={}
for m in re.finditer(r'message\s+(\w+)\s*\{',source):
    start=m.end();depth=1;end=start
    while depth:
        depth+=(source[end]=='{')-(source[end]=='}');end+=1
    fields=[]
    for repeated,typ,name,num in re.findall(r'\b(?:(optional|repeated)\s+)?(\w+)\s+(\w+)\s*=\s*(\d+)\s*;',source[start:end-1]):
        kind={'bytes':'b','uint32':'u32','uint64':'u64','int64':'i64','bool':'bool'}.get(typ)
        if kind is None:kind='e'+str(enums[typ]) if typ in enums else 'm'+typ
        fields.append([int(num),kind,repeated=='repeated'])
    schemas[m.group(1)]=sorted(fields)
(root/'wire/schema.json').write_text(json.dumps(schemas,indent=2)+'\n')
(root/'schema-data.mjs').write_text('// Generated by schema-generate.py.\nexport default '+json.dumps(schemas,separators=(',',':'))+';\n')
(root/'go/labwire/schema_data.go').write_text('// Generated by schema-generate.py.\npackage labwire\nvar schemaRules=map[string][]schemaRule{\n'+''.join('"'+name+'":{'+','.join('{'+str(n)+',"'+kind+'",'+str(rep).lower()+'}' for n,kind,rep in fields)+'},\n' for name,fields in schemas.items())+'}\n')
(root/'SchemaData.java').write_text('// Generated by schema-generate.py.\npackage example.transportlab;\nimport java.util.*;\nfinal class SchemaData {static final Map<String,Schema.Rule[]> rules=new HashMap<>();static{\n'+''.join('rules.put("'+name+'",new Schema.Rule[]{'+','.join('new Schema.Rule('+str(n)+',"'+kind+'",'+str(rep).lower()+')' for n,kind,rep in fields)+'});\n' for name,fields in schemas.items())+'}}\n')
(root/'SchemaData.swift').write_text('// Generated by schema-generate.py.\nimport Foundation\nextension Schema {static let rules:[String:[Rule]]=[\n'+''.join('"'+name+'":['+','.join('Rule('+str(n)+',"'+kind+'",'+str(rep).lower()+')' for n,kind,rep in fields)+'],\n' for name,fields in schemas.items())+']}\n')
print('draft schemas:',len(schemas))

bounds=json.loads((root/'wire/body-bounds.json').read_text())
(root/'schema-bounds.mjs').write_text('// Generated by schema-generate.py.\nexport default '+json.dumps({name:{n:list(map(str,v)) for n,v in fs.items()} for name,fs in bounds.items()},separators=(',',':'))+';\n')
with (root/'go/labwire/schema_data.go').open('a') as f:f.write('var schemaBounds=map[string]map[uint64][2]uint64{'+','.join('"'+name+'":{'+','.join(n+':{'+str(v[0])+','+str(v[1])+'}' for n,v in fs.items())+'}' for name,fs in bounds.items())+'}\n')
with (root/'SchemaData.java').open('a') as f:f.write('final class SchemaBounds {static final Map<String,Map<Integer,long[]>> bounds=Map.ofEntries('+','.join('Map.entry("'+name+'",Map.ofEntries('+','.join('Map.entry('+n+',new long[]{'+str(v[0])+'L,'+str(v[1] if v[1]<2**63 else -1)+'L})' for n,v in fs.items())+'))' for name,fs in bounds.items())+');}\n')
with (root/'SchemaData.swift').open('a') as f:f.write('extension Schema {static let bounds:[String:[Int:[UInt64]]]=['+','.join('"'+name+'":['+','.join(n+':['+str(v[0])+','+str(v[1])+']' for n,v in fs.items())+']' for name,fs in bounds.items())+']}\n')

# Tiny expression compiler: one reviewable semantic contract, four independent
# evaluators. No runtime eval and no normalization of signed bytes.
import ast
relations=json.loads((root/'wire/body-relations.json').read_text())
def expression(node,lang):
    if isinstance(node,ast.Constant):return str(node.value)+('n' if lang=='js' else 'L' if lang=='java' else '')
    if isinstance(node,ast.Call):return node.func.id+'('+str(node.args[0].value)+')'
    if isinstance(node,ast.UnaryOp):return '!('+expression(node.operand,lang)+')'
    if isinstance(node,ast.BoolOp):return '('+(' && ' if isinstance(node.op,ast.And) else ' || ').join(expression(v,lang) for v in node.values)+')'
    if isinstance(node,ast.Compare):
        op={ast.Eq:'==',ast.Gt:'>',ast.GtE:'>=',ast.Lt:'<',ast.LtE:'<='}[type(node.ops[0])];a=expression(node.left,lang);b=expression(node.comparators[0],lang)
        if lang=='java':return '(Long.compareUnsigned('+a+','+b+')'+op+'0)'
        return '('+a+op+b+')'
    raise ValueError(node)
outputs={
'go':('go/labwire/schema_data.go', 'func schemaRelations(name string,values map[uint64][]Field)bool{v:=func(n uint64)uint64{if len(values[n])==0{return 0};return values[n][0].U};size:=func(n uint64)uint64{if len(values[n])==0{return 0};return uint64(len(values[n][0].B))};has:=func(n uint64)bool{return len(values[n])>0};switch name{',lambda n,e:'case "'+n+'":return '+e+';', '};return true}\n'),
'js':('schema-relations.mjs', '// Generated by schema-generate.py.\nexport function relations(name,values){const v=n=>values.get(n)?.[0]?.value??0n,size=n=>BigInt(values.get(n)?.[0]?.value?.length??0),has=n=>(values.get(n)?.length??0)>0;switch(name){',lambda n,e:'case "'+n+'":return '+e+';', 'default:return true}}\n'),
'java':('SchemaData.java', 'final class SchemaRelations{static boolean valid(String name,Map<Integer,List<Wire.Field>> values){class Get{long v(int n){return values.containsKey(n)&&!values.get(n).isEmpty()?values.get(n).get(0).u:0;}long size(int n){return values.containsKey(n)&&!values.get(n).isEmpty()?values.get(n).get(0).b.length:0;}boolean has(int n){return values.containsKey(n)&&!values.get(n).isEmpty();}}Get g=new Get();switch(name){',lambda n,e:'case "'+n+'":return '+e.replace('v(','g.v(').replace('size(','g.size(').replace('has(','g.has(')+';', 'default:return true;}}}\n'),
'swift':('SchemaData.swift', 'extension Schema{static func relations(_ name:String,_ values:[Int:[Wire.Field]])->Bool{func v(_ n:Int)->UInt64{values[n]?.first?.value ?? 0};func size(_ n:Int)->UInt64{UInt64(values[n]?.first?.data.count ?? 0)};func has(_ n:Int)->Bool{!(values[n] ?? []).isEmpty};switch name{',lambda n,e:'case "'+n+'":return '+e+';', 'default:return true}}}\n')}
for lang,(file,head,row,tail) in outputs.items():
    with (root/file).open('w' if lang=='js' else 'a') as f:f.write(head+''.join(row(name,expression(ast.parse(expr,mode='eval').body,lang)) for name,expr in relations.items())+tail)

if scratch:
    for path in root.rglob('*'):
        if path.is_file():assert path.read_bytes()==(original/path.relative_to(root)).read_bytes(),str(path.relative_to(root))+' is stale'
    scratch.cleanup()
